import encodings.idna, json, sys, unicodedata
assert sys.version_info[:3] == (3, 14, 7)
assert unicodedata.unidata_version == "16.0.0"
def fault(error):
    result = {"name": type(error).__name__, "message": str(error), "suppressContext": error.__suppress_context__}
    if isinstance(error, (UnicodeEncodeError, UnicodeDecodeError)):
        result.update(encoding=error.encoding, object=list(map(ord, error.object)) if isinstance(error.object, str) else list(error.object), start=str(error.start), end=str(error.end), reason=error.reason)
    if error.__context__ is not None:
        result["context"] = fault(error.__context__)
    return result
rows = []
for case in json.load(sys.stdin)["cases"]:
    row = {"kind": case["kind"], "input": case["input"]}
    value = "".join(map(chr, row["input"])) if row["kind"] == "text" else bytes(row["input"])
    try:
        row["result"] = list(map(ord, encodings.idna.ToUnicode(value)))
    except Exception as error:
        row["error"] = fault(error)
    rows.append(row)
json.dump(rows, sys.stdout, ensure_ascii=True)
